arguments.file_text:
:root {
  --bg: #faf8f5;
  --surface: #ffffff;
  --surface-alt: #f1ede6;
  --ink: #1a1a1a;
  --ink-soft: #4a4a4a;
  --ink-muted: #6b6b6b;
  --line: #e6e1d8;
  --accent: #2a4a3a;
  --accent-ink: #ffffff;
  --highlight: #d94f2a;
  --sale: #b8341a;
  --radius: 14px;
  --radius-sm: 8px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(20, 18, 14, 0.04), 0 1px 3px rgba(20, 18, 14, 0.06);
  --shadow-md: 0 4px 12px rgba(20, 18, 14, 0.06), 0 2px 4px rgba(20, 18, 14, 0.04);
  --maxw: 1240px;
  --gutter: clamp(16px, 4vw, 40px);
  --font-sans: 'Inter', system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-display: 'Fraunces', Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--ink);
  background: var(--bg);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; }

a {
  color: inherit;
  text-decoration: none;
}

a:hover { text-decoration: underline; text-underline-offset: 3px; }

button {
  font: inherit;
  cursor: pointer;
}

/* Focus indicators (>= 3:1 contrast) */
:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--ink);
  color: #fff;
  padding: 10px 14px;
  border-radius: 6px;
  z-index: 1000;
  font-weight: 600;
}
.skip-link:focus { top: 12px; text-decoration: none; }

.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

/* ---------- Announcement bar ---------- */
.announce {
  background: var(--ink);
  color: #f5f1ea;
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-align: center;
  padding: 9px var(--gutter);
}
.announce strong { color: #fff; font-weight: 600; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 248, 245, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.site-header__inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
}
.brand {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.55rem;
  letter-spacing: -0.01em;
}
.brand a { display: inline-block; padding: 4px 2px; }

.primary-nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 28px;
  justify-content: center;
}
.primary-nav a {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ink-soft);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  border-bottom-color: var(--ink);
}
.primary-nav a:hover { color: var(--ink); text-decoration: none; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  background: transparent;
  border: 0;
  padding: 8px;
  border-radius: 50%;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.icon-btn svg { width: 22px; height: 22px; }
.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--highlight);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  padding: clamp(40px, 7vw, 88px) 0 clamp(48px, 8vw, 96px);
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
}
.hero__eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(42, 74, 58, 0.08);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 22px;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.4rem, 5.6vw, 4.4rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 0 0 22px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero__lede {
  font-size: 1.08rem;
  color: var(--ink-soft);
  max-width: 46ch;
  margin: 0 0 32px;
}
.hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--surface-alt);
  box-shadow: var(--shadow-md);
}
.hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.hero__badge {
  position: absolute;
  bottom: 18px;
  left: 18px;
  background: rgba(255, 255, 255, 0.96);
  color: var(--ink);
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 0.85rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 10px;
  box-shadow: var(--shadow-sm);
}
.hero__badge .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--highlight);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid transparent;
  transition: transform 0.08s ease, background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  text-decoration: none;
  min-height: 44px;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn--primary {
  background: var(--ink);
  color: #fff;
}
.btn--primary:hover { background: #2d2d2d; }
.btn--ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn--ghost:hover { background: var(--ink); color: #fff; }
.btn--accent {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn--accent:hover { background: #1f3a2c; }
.btn--block { width: 100%; justify-content: center; }

/* ---------- Section primitives ---------- */
section { padding: clamp(56px, 8vw, 96px) 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head__text { max-width: 60ch; }
.section-eyebrow {
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
  margin: 0 0 10px;
}
h2.section-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  letter-spacing: -0.01em;
  line-height: 1.1;
  margin: 0;
}
.section-head__link {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ink);
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}
.section-head__link:hover { color: var(--accent); border-color: var(--accent); text-decoration: none; }

/* ---------- Categories strip ---------- */
.categories {
  padding: clamp(32px, 4vw, 48px) 0 0;
}
.categories__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 16px 8px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  text-align: center;
  font-weight: 500;
  font-size: 0.92rem;
  transition: border-color 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}
.category-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
  text-decoration: none;
}
.category-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
}

/* ---------- Featured products grid ---------- */
.products-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(16px, 2vw, 24px);
}
.product-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: #d9d2c4;
}
.product-card__media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--surface-alt);
  overflow: hidden;
}
.product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-card__media img { transform: scale(1.04); }
.product-card__tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--ink);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 6px;
}
.product-card__tag--new { background: var(--accent); }
.product-card__tag--sale { background: var(--sale); }
.product-card__wish {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(255,255,255,0.95);
  border: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  box-shadow: var(--shadow-sm);
}
.product-card__wish svg { width: 18px; height: 18px; }
.product-card__wish:hover { color: var(--highlight); }
.product-card__wish[aria-pressed="true"] { color: var(--highlight); }
.product-card__wish[aria-pressed="true"] svg { fill: currentColor; }

.product-card__body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-card__category {
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
}
.product-card__name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.08rem;
  line-height: 1.25;
  margin: 0;
  letter-spacing: -0.005em;
}
.product-card__name a { color: inherit; }
.product-card__name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product-card__rating {
  font-size: 0.82rem;
  color: var(--ink-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.product-card__rating .stars { color: #c98a14; letter-spacing: 1px; }
.product-card__price {
  margin-top: auto;
  padding-top: 8px;
  font-size: 1rem;
  font-weight: 600;
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.product-card__price .old {
  font-weight: 400;
  color: var(--ink-muted);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.product-card__price .save {
  font-size: 0.75rem;
  color: var(--sale);
  font-weight: 700;
  letter-spacing: 0.04em;
}

/* ---------- Deals banner ---------- */
.deals { background: linear-gradient(135deg, #f5efe4 0%, #ece4d2 100%); }
.deals__grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 18px;
}
.deal-card {
  border-radius: var(--radius-lg);
  padding: 32px;
  background: var(--surface);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
}
.deal-card--feature {
  background: var(--accent);
  color: #f4ede0;
  border-color: transparent;
}
.deal-card--feature .deal-card__eyebrow { color: #c8d6cd; }
.deal-card--warm { background: #f3d8c5; color: #4a1f0f; border-color: transparent; }
.deal-card--warm .deal-card__eyebrow { color: #8a3a1c; }
.deal-card__eyebrow {
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  margin: 0 0 12px;
  color: var(--ink-muted);
}
.deal-card__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.5rem, 2.6vw, 2rem);
  line-height: 1.05;
  letter-spacing: -0.01em;
  margin: 0 0 14px;
}
.deal-card__desc {
  font-size: 0.95rem;
  margin: 0 0 24px;
  opacity: 0.92;
  max-width: 32ch;
}
.deal-card__cta {
  align-self: flex-start;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1.5px solid currentColor;
  padding-bottom: 2px;
  font-size: 0.95rem;
}
.deal-card__cta:hover { text-decoration: none; gap: 10px; }

/* Countdown */
.countdown {
  display: flex;
  gap: 10px;
  margin: 12px 0 22px;
}
.countdown__cell {
  background: rgba(255,255,255,0.18);
  border-radius: 10px;
  padding: 8px 12px;
  text-align: center;
  min-width: 56px;
  font-variant-numeric: tabular-nums;
}
.countdown__num {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  display: block;
  line-height: 1;
}
.countdown__label {
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-top: 4px;
  display: block;
}

/* ---------- Editorial ---------- */
.editorial__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(20px, 2.4vw, 32px);
}
.story {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.story__media {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-alt);
}
.story__media img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.story:hover .story__media img { transform: scale(1.03); }
.story__meta {
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
  display: flex;
  gap: 10px;
  align-items: center;
}
.story__meta .dot-sep { color: var(--line); }
.story__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.35rem;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0;
}
.story__title a { color: inherit; }
.story__excerpt {
  color: var(--ink-soft);
  font-size: 0.95rem;
  margin: 0;
}

/* ---------- Value props ---------- */
.values {
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.values__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.value-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.value-item__icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--accent);
}
.value-item__icon svg { width: 22px; height: 22px; }
.value-item h3 {
  margin: 0 0 4px;
  font-size: 0.98rem;
  font-weight: 600;
}
.value-item p {
  margin: 0;
  font-size: 0.88rem;
  color: var(--ink-muted);
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--ink);
  color: #f4f1eb;
}
.newsletter__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.8rem, 3.4vw, 2.4rem);
  margin: 0 0 12px;
  line-height: 1.1;
  letter-spacing: -0.01em;
}
.newsletter p { color: #c9c4ba; margin: 0; max-width: 42ch; }
.newsletter form {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.newsletter__field {
  flex: 1 1 220px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.newsletter__field label {
  font-size: 0.85rem;
  font-weight: 500;
  color: #d8d3c9;
}
.newsletter__field input {
  font: inherit;
  padding: 14px 16px;
  border-radius: 999px;
  border: 1px solid #3a3a38;
  background: #232322;
  color: #fff;
  min-height: 48px;
}
.newsletter__field input::placeholder { color: #8d8a82; }
.newsletter__field input:focus-visible {
  outline: 2px solid #f5deb8;
  outline-offset: 2px;
  border-color: transparent;
}
.newsletter__hint { font-size: 0.78rem; color: #a09c92; }
.newsletter__submit {
  align-self: flex-end;
}
.newsletter__status {
  margin-top: 14px;
  font-size: 0.92rem;
  color: #b9e8c5;
  min-height: 1.4em;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--bg);
  padding: 56px 0 24px;
  border-top: 1px solid var(--line);
}
.site-footer__grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 36px;
  margin-bottom: 40px;
}
.site-footer h2 {
  font-size: 0.82rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--ink);
  margin: 0 0 14px;
}
.site-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.site-footer a { color: var(--ink-soft); font-size: 0.92rem; }
.site-footer a:hover { color: var(--ink); }
.site-footer__brand p { color: var(--ink-muted); font-size: 0.92rem; margin: 12px 0 0; max-width: 38ch; }
.site-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border-top: 1px solid var(--line);
  padding-top: 22px;
  font-size: 0.84rem;
  color: var(--ink-muted);
}
.site-footer__legal { display: flex; gap: 18px; flex-wrap: wrap; }

/* ---------- Visually hidden ---------- */
.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories__list { grid-template-columns: repeat(3, 1fr); }
  .deals__grid { grid-template-columns: 1fr 1fr; }
  .deal-card--feature { grid-column: 1 / -1; }
  .editorial__grid { grid-template-columns: 1fr 1fr; }
  .editorial__grid .story:nth-child(3) { grid-column: 1 / -1; }
  .values__list { grid-template-columns: 1fr 1fr; }
  .site-footer__grid { grid-template-columns: 1fr 1fr; }
  .newsletter__inner { grid-template-columns: 1fr; }
}

@media (max-width: 720px) {
  .site-header__inner { grid-template-columns: auto 1fr auto; }
  .primary-nav {
    position: absolute;
    inset: 100% 0 auto 0;
    background: var(--bg);
    border-bottom: 1px solid var(--line);
    padding: 12px var(--gutter) 18px;
    display: none;
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul { flex-direction: column; gap: 4px; align-items: stretch; }
  .primary-nav a { padding: 12px 4px; display: block; border-bottom: 1px solid var(--line); }
  .primary-nav a:last-child { border-bottom: 0; }
  .menu-toggle { display: inline-flex; }
  .hero__grid { grid-template-columns: 1fr; }
  .hero__media { order: -1; aspect-ratio: 4/3; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories__list { grid-template-columns: repeat(2, 1fr); }
  .deals__grid { grid-template-columns: 1fr; }
  .editorial__grid { grid-template-columns: 1fr; }
  .editorial__grid .story:nth-child(3) { grid-column: auto; }
  .values__list { grid-template-columns: 1fr; }
  .site-footer__grid { grid-template-columns: 1fr; }
  .section-head { align-items: flex-start; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .category-card, .product-card, .deal-card, .icon-btn {
    border: 1px solid CanvasText;
  }
  .btn--primary, .btn--accent { background: ButtonFace; color: ButtonText; }
  :focus-visible { outline-color: Highlight; }
}

