function useCountdown(target) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const minutes = Math.floor((diff % 3600000) / 60000);
  const seconds = Math.floor((diff % 60000) / 1000);
  return { days, hours, minutes, seconds, diff };
}

function Countdown({ target }) {
  const { days, hours, minutes, seconds, diff } = useCountdown(target);
  const pad = (n) => String(n).padStart(2, "0");
  const label = `Sale ends in ${days} days, ${hours} hours, ${minutes} minutes, ${seconds} seconds`;
  return (
    <div className="countdown" role="timer" aria-live="off" aria-label={label}>
      {[
        { v: days, l: "Days" },
        { v: hours, l: "Hours" },
        { v: minutes, l: "Min" },
        { v: seconds, l: "Sec" },
      ].map(({ v, l }) => (
        <div className="countdown__cell" key={l}>
          <span className="countdown__num">{pad(v)}</span>
          <span className="countdown__label">{l}</span>
        </div>
      ))}
    </div>
  );
}

