  font-weight: 600;
  font-size: 1.55rem;
  letter-spacing: -0.01em;
}
.brand a { display: inline-block; padding: 4px 2px; }

.primary-nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 28px;
  justify-content: center;
}
.primary-nav a {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ink-soft);
  padding: 6px 2px;
  border-bottom: 2px solid transparent;
}
.primary-nav a[aria-current="page"] {
  color: var(--ink);
  border-bottom-color: var(--ink);
}
.primary-nav a:hover { color: var(--ink); text-decoration: none; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.icon-btn {
  background: transparent;
  border: 0;
  padding: 8px;
  border-radius: 50%;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.icon-btn:hover { background: var(--surface-alt); }
.icon-btn svg { width: 22px; height: 22px; }
.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--highlight);
  color: #fff;
  font-size: 0.68rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  padding: clamp(40px, 7vw, 88px) 0 clamp(48px, 8vw, 96px);
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 5vw, 64px);
  align-items: center;
}
.hero__eyebrow {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(42, 74, 58, 0.08);
  padding: 6px 12px;
  border-radius: 999px;
  margin-bottom: 22px;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.4rem, 5.6vw, 4.4rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 0 0 22px;
}
.hero h1 em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero__lede {
  font-size: 1.08rem;
  color: var(--ink-soft);
  max-width: 46ch;
  margin: 0 0 32px;
}
.hero__ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.hero__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--surface-alt);
  box-shadow: var(--shadow-md);
}
.hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.hero__badge {
  position: absolute;
  bottom: 18px;
  left: 18px;
  background: rgba(255, 255, 255, 0.96);
  color: var(--ink);
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 0.85rem;
  font-weight: 500;
