  align-items: center;
  gap: 10px;
  box-shadow: var(--shadow-sm);
}
.hero__badge .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--highlight);
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
