}
.btn--ghost:hover { background: var(--ink); color: #fff; }
.btn--accent {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn--accent:hover { background: #1f3a2c; }
.btn--block { width: 100%; justify-content: center; }

/* ---------- Section primitives ---------- */
section { padding: clamp(56px, 8vw, 96px) 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.section-head__text { max-width: 60ch; }
.section-eyebrow {
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
  margin: 0 0 10px;
}
h2.section-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.8rem, 3.4vw, 2.6rem);
  letter-spacing: -0.01em;
  line-height: 1.1;
  margin: 0;
}
.section-head__link {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ink);
  border-bottom: 1.5px solid var(--ink);
  padding-bottom: 2px;
}
.section-head__link:hover { color: var(--accent); border-color: var(--accent); text-decoration: none; }

/* ---------- Categories strip ---------- */
.categories {
  padding: clamp(32px, 4vw, 48px) 0 0;
}
.categories__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 16px 8px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--ink);
  text-align: center;
  font-weight: 500;
  font-size: 0.92rem;
  transition: border-color 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}
.category-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
  text-decoration: none;
}
.category-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
}

/* ---------- Featured products grid ---------- */
.products-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(16px, 2vw, 24px);
}
.product-card {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  position: relative;
}
.product-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: #d9d2c4;
}
.product-card__media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--surface-alt);
  overflow: hidden;
}
.product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.product-card:hover .product-card__media img { transform: scale(1.04); }
.product-card__tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--ink);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 6px;
}
.product-card__tag--new { background: var(--accent); }
.product-card__tag--sale { background: var(--sale); }
.product-card__wish {
  position: absolute;
  z-index: 2;
  top: 10px;
  right: 10px;
  background: rgba(255,255,255,0.95);
  border: 0;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--ink);
  box-shadow: var(--shadow-sm);
}
.product-card__wish svg { width: 18px; height: 18px; }
.product-card__wish:hover { color: var(--highlight); }
.product-card__wish[aria-pressed="true"] { color: var(--highlight); }
.product-card__wish[aria-pressed="true"] svg { fill: currentColor; }

.product-card__body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}
.product-card__category {
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
}
.product-card__name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.08rem;
  line-height: 1.25;
  margin: 0;
  letter-spacing: -0.005em;
}
.product-card__name a { color: inherit; }
.product-card__name a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product-card__rating {
  font-size: 0.82rem;
  color: var(--ink-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.product-card__rating .stars { color: #c98a14; letter-spacing: 1px; }
.product-card__price {
  margin-top: auto;
  padding-top: 8px;
  font-size: 1rem;
  font-weight: 600;
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.product-card__price .old {
  font-weight: 400;
  color: var(--ink-muted);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.product-card__price .save {
  font-size: 0.75rem;
  color: var(--sale);
  font-weight: 700;
  letter-spacing: 0.04em;
}

/* ---------- Deals banner ---------- */
.deals { background: linear-gradient(135deg, #f5efe4 0%, #ece4d2 100%); }
.deals__grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  gap: 18px;
}
.deal-card {
  border-radius: var(--radius-lg);
