  background: var(--surface);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  position: relative;
  overflow: hidden;
  border: 1px solid var(--line);
}
.deal-card--feature {
  background: var(--accent);
  color: #f4ede0;
  border-color: transparent;
}
.deal-card--feature .deal-card__eyebrow { color: #c8d6cd; }
.deal-card--warm { background: #f3d8c5; color: #4a1f0f; border-color: transparent; }
.deal-card--warm .deal-card__eyebrow { color: #8a3a1c; }
.deal-card__eyebrow {
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  margin: 0 0 12px;
  color: var(--ink-muted);
}
.deal-card__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.5rem, 2.6vw, 2rem);
  line-height: 1.05;
  letter-spacing: -0.01em;
  margin: 0 0 14px;
}
.deal-card__desc {
  font-size: 0.95rem;
  margin: 0 0 24px;
  opacity: 0.92;
  max-width: 32ch;
}
.deal-card__cta {
  align-self: flex-start;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1.5px solid currentColor;
  padding-bottom: 2px;
  font-size: 0.95rem;
}
.deal-card__cta:hover { text-decoration: none; gap: 10px; }

/* Countdown */
.countdown {
  display: flex;
  gap: 10px;
  margin: 12px 0 22px;
}
.countdown__cell {
  background: rgba(255,255,255,0.18);
  border-radius: 10px;
  padding: 8px 12px;
  text-align: center;
  min-width: 56px;
  font-variant-numeric: tabular-nums;
}
.countdown__num {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  display: block;
  line-height: 1;
}
.countdown__label {
  font-size: 0.68rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-top: 4px;
  display: block;
}

/* ---------- Editorial ---------- */
.editorial__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(20px, 2.4vw, 32px);
}
.story {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.story__media {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--surface-alt);
}
.story__media img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.story:hover .story__media img { transform: scale(1.03); }
.story__meta {
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 600;
  display: flex;
  gap: 10px;
  align-items: center;
}
.story__meta .dot-sep { color: var(--line); }
.story__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.35rem;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0;
}
.story__title a { color: inherit; }
.story__excerpt {
  color: var(--ink-soft);
  font-size: 0.95rem;
  margin: 0;
}

/* ---------- Value props ---------- */
.values {
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.values__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.value-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.value-item__icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--surface-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--accent);
}
.value-item__icon svg { width: 22px; height: 22px; }
.value-item h3 {
  margin: 0 0 4px;
  font-size: 0.98rem;
  font-weight: 600;
}
.value-item p {
  margin: 0;
  font-size: 0.88rem;
  color: var(--ink-muted);
}

