.newsletter {
  background: var(--ink);
  color: #f4f1eb;
}
.newsletter__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(1.8rem, 3.4vw, 2.4rem);
  margin: 0 0 12px;
  line-height: 1.1;
  letter-spacing: -0.01em;
}
.newsletter p { color: #c9c4ba; margin: 0; max-width: 42ch; }
.newsletter form {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.newsletter__field {
  flex: 1 1 220px;
  display: flex;
  flex-direction: column;
  gap: 6px;
