}
.site-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.site-footer a { color: var(--ink-soft); font-size: 0.92rem; }
.site-footer a:hover { color: var(--ink); }
.site-footer__brand p { color: var(--ink-muted); font-size: 0.92rem; margin: 12px 0 0; max-width: 38ch; }
.site-footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border-top: 1px solid var(--line);
  padding-top: 22px;
  font-size: 0.84rem;
  color: var(--ink-muted);
}
.site-footer__legal { display: flex; gap: 18px; flex-wrap: wrap; }

/* ---------- Visually hidden ---------- */
.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(3, 1fr); }
  .categories__list { grid-template-columns: repeat(3, 1fr); }
  .deals__grid { grid-template-columns: 1fr 1fr; }
  .deal-card--feature { grid-column: 1 / -1; }
  .editorial__grid { grid-template-columns: 1fr 1fr; }
  .editorial__grid .story:nth-child(3) { grid-column: 1 / -1; }
  .values__list { grid-template-columns: 1fr 1fr; }
  .site-footer__grid { grid-template-columns: 1fr 1fr; }
  .newsletter__inner { grid-template-columns: 1fr; }
}

@media (max-width: 720px) {
  .site-header__inner { grid-template-columns: auto 1fr auto; }
  .primary-nav {
    position: absolute;
    inset: 100% 0 auto 0;
    background: var(--bg);
    border-bottom: 1px solid var(--line);
    padding: 12px var(--gutter) 18px;
    display: none;
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul { flex-direction: column; gap: 4px; align-items: stretch; }
  .primary-nav a { padding: 12px 4px; display: block; border-bottom: 1px solid var(--line); }
  .primary-nav a:last-child { border-bottom: 0; }
  .menu-toggle { display: inline-flex; }
  .hero__grid { grid-template-columns: 1fr; }
  .hero__media { order: -1; aspect-ratio: 4/3; }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .categories__list { grid-template-columns: repeat(2, 1fr); }
  .deals__grid { grid-template-columns: 1fr; }
  .editorial__grid { grid-template-columns: 1fr; }
  .editorial__grid .story:nth-child(3) { grid-column: auto; }
  .values__list { grid-template-columns: 1fr; }
  .site-footer__grid { grid-template-columns: 1fr; }
  .section-head { align-items: flex-start; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .category-card, .product-card, .deal-card, .icon-btn {
    border: 1px solid CanvasText;
  }
  .btn--primary, .btn--accent { background: ButtonFace; color: ButtonText; }
  :focus-visible { outline-color: Highlight; }
}
